// Common alternative spellings/abbreviations → canonical name.
const ALIASES = {
    usa: 'United States',
    us: 'United States',
    'u.s.': 'United States',
    'u.s.a.': 'United States',
    'united states of america': 'United States',
    america: 'United States',
    uk: 'United Kingdom',
    'u.k.': 'United Kingdom',
    'great britain': 'United Kingdom',
    britain: 'United Kingdom',
    england: 'United Kingdom',
    uae: 'United Arab Emirates',
    'south korea': 'South Korea',
    'republic of korea': 'South Korea',
    korea: 'South Korea',
    'côte d’ivoire': 'Ivory Coast',
    "cote d'ivoire": 'Ivory Coast',
};
const BY_LOWER = new Map(COUNTRIES.map((c) => [c.toLowerCase(), c]));
/**
 * Normalises a typed Location value to its canonical country name when it names
 * a country (case-insensitive, plus a few common aliases). Anything else — a
 * city, a region, blank — is returned trimmed and unchanged, so free text still
 * works.
 */
export function canonicalCountry(value) {
    const v = value.trim();
    if (!v)
        return '';
    const lower = v.toLowerCase();
    return BY_LOWER.get(lower) ?? ALIASES[lower] ?? v;
}
